mapper.select:
SELECT m.id, m.warehouse_id AS warehouseId, m.sku_id AS skuId, ps.sku_code AS skuCode,
    m.quantity_delta AS quantityDelta, m.quantity_after AS quantityAfter, m.reason,
    m.created_by AS createdBy, m.created_at AS createdAt
FROM warehouse_inventory_movement m LEFT JOIN product_sku ps ON ps.id = m.sku_id
WHERE m.warehouse_id = #{warehouseId}
AND m.sku_id = #{skuId}
ORDER BY m.id DESC LIMIT #{limit}
